INSERT INTO public.apps VALUES ('51c7047c-4c78-4cda-85c2-74a847609601', 'openclaw-desktop', 'OpenClaw Desktop', 'The AI assistant that actually does things', 'OpenClaw is a self-hosted, open-source AI agent that runs locally on your computer. Control it via WhatsApp, Telegram, Discord, Signal, or Slack. It can manage your files, automate workflows, control your browser, send emails, and much more. With 145k+ GitHub stars, it''s the fastest-growing open-source AI agent platform.', 'https://openclaw.ai/logo.png', 'openclaw', 'https://openclaw.ai', 'https://github.com/openclaw/openclaw', true, true, 145000, 2500000, 890000, '{macOS,"Windows (WSL2)",Linux,"Raspberry Pi"}', '{"Control your PC via WhatsApp, Telegram, Discord, Signal, or Slack","3,000+ community skills available on ClawHub","Browser automation with Playwright","File management and shell command execution","Email and calendar integration","Smart home and IoT control","Persistent memory across sessions","Works with Claude, GPT, DeepSeek, or local Ollama models"}', '{WhatsApp,Telegram,Discord,Signal,Slack,Gmail,Notion,Obsidian,GitHub}', '2026-02-08 18:50:29.221356', '2026-02-08 18:50:29.221356') ON CONFLICT DO NOTHING;
INSERT INTO public.apps VALUES ('69d0f1b5-1707-425f-aa76-7ead4f51da49', 'excalidraw-agent', 'Excalidraw Agent', 'Natural language to visual diagrams', 'Say "draw this flow" and get instant diagrams. Natural language to visual flowcharts, architecture maps, and wireframes. Powered by Excalidraw and OpenClaw, this app turns your words into professional diagrams in seconds.', '/images/featured/app-excalidraw-agent.png', 'swiftlysingh', 'https://github.com/swiftlysingh', 'https://github.com/swiftlysingh', true, true, 2400, 18000, 5200, '{Web,macOS,Linux}', '{"Natural language to flowcharts and diagrams","Architecture map generation","Wireframe creation from descriptions","Export to PNG, SVG, and Excalidraw format","Real-time collaborative editing","Integration with OpenClaw skills"}', '{OpenClaw,Excalidraw,GitHub}', '2026-02-08 18:50:29.221356', '2026-02-08 18:50:29.221356') ON CONFLICT DO NOTHING;
INSERT INTO public.skills VALUES ('26ad708a-b65b-435a-bf9c-694191df6ff5', 'caldav-calendar', 'CalDAV Calendar', 'Sync iCloud, Google, Fastmail, Nextcloud calendars on Linux', 'Universal calendar integration for OpenClaw agents. Sync and manage events across iCloud, Google Calendar, Fastmail, Nextcloud, and any CalDAV-compatible provider. Create, update, delete events and check availability.', 'Asleep123', NULL, '1.0.3', 'productivity', 4, 3658, 982, 3658, 85, 'verified', true, false, NULL, '{"Multi-provider sync","Event management","Availability checking","Recurring events","Calendar sharing"}', '{calendar,caldav,scheduling,productivity}', 'https://github.com/Asleep123/caldav-calendar', 'https://clawhub.ai/Asleep123/caldav-calendar', 'MIT', '2026-02-08 19:33:30.306869', '2026-02-08 19:33:30.306869', '97e4e63e-3f67-486e-afa2-771366b61e24', 'low', '15cf0275-7d52-433c-9ccb-1d92ea62e99c') ON CONFLICT DO NOTHING;
INSERT INTO public.skills VALUES ('7fa4dd9a-e6b3-4927-9b51-dc76a9f4eec7', 'email', 'Email', 'Send, read, search, and organize emails across multiple providers', 'Multi-provider email integration for OpenClaw agents. Send, read, search, and organize emails across Gmail, Outlook, IMAP, and other providers. Supports attachments, threading, labels, and smart filtering.', '0xterrybit', NULL, '1.1.0', 'productivity', 8, 3120, 876, 3120, 87, 'verified', true, false, NULL, '{"Multi-provider support","Send and receive","Search and filter","Attachment handling","Thread management"}', '{email,gmail,outlook,communication}', 'https://github.com/0xterrybit/claw-email', 'https://clawhub.ai/0xterrybit/email', 'MIT', '2026-02-08 19:33:30.306869', '2026-02-08 19:33:30.306869', 'c59d8a11-3553-4dbb-bb71-fca59fc11531', 'low', '6c284c5c-77f8-44f9-819a-cf56162c3b95') ON CONFLICT DO NOTHING;
INSERT INTO public.skills VALUES ('3f85deee-17c0-4f90-ae94-d1232d9f9e8d', 'api-connector', 'API Connector', 'Universal REST API client with OAuth and rate limiting', 'Connect to any REST API with built-in authentication handling, rate limiting, and response caching. Supports OAuth 1.0, 2.0, API keys, and custom auth schemes.', 'apidev', NULL, '3.0.1', 'integration', 67, 2340, 156, 890, 88, 'verified', true, true, NULL, '{"OAuth 1.0 and 2.0 support","API key authentication","Automatic rate limiting","Response caching","Retry with backoff","Request/response logging"}', '{api,rest,oauth,integration}', NULL, NULL, 'MIT', '2026-02-05 09:20:04.700705', '2026-02-05 09:20:04.700705', '1d7c658b-5222-4642-a7d9-d016a2a6d9b9', 'unreviewed', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.skills VALUES ('24df78a2-287e-4b66-b4d5-0df8f9a0c202', 'github', 'GitHub', 'Issues, PRs, CI runs, and advanced queries via gh CLI', 'Full GitHub integration for OpenClaw agents. Manage issues, pull requests, CI/CD runs, code reviews, and advanced repository queries — all through natural language. Powered by the gh CLI.', 'steipete', NULL, '1.4.2', 'productivity', 14, 7504, 2841, 7504, 92, 'verified', true, true, NULL, '{"Issue management","Pull request workflows","CI/CD monitoring","Code review automation","Repository search"}', '{github,git,ci-cd,devtools}', 'https://github.com/anthropics/claw-github-skill', 'https://clawhub.ai/steipete/github', 'MIT', '2026-02-08 19:33:30.306869', '2026-02-08 19:33:30.306869', 'e93e4318-477b-405a-b046-9da710710191', 'low', 'eeccb5f5-fa6f-4cf5-9d09-c56c9b21cf88') ON CONFLICT DO NOTHING;
