INSERT INTO public.skills VALUES ('7827e683-fb7f-4836-b249-43443c7cd0a2', 'notion', 'Notion', 'Create and manage pages, databases, and blocks via Notion API', 'Full Notion workspace integration for OpenClaw. Create pages, query databases, manage blocks, search content, and automate workspace workflows through the official Notion API.', 'steipete', NULL, '1.2.1', 'productivity', 11, 3430, 1205, 3430, 90, 'verified', true, false, NULL, '{"Page creation","Database queries","Block management","Content search","Workspace automation"}', '{notion,notes,knowledge-base,productivity}', 'https://github.com/anthropics/claw-notion-skill', 'https://clawhub.ai/steipete/notion', 'MIT', '2026-02-08 19:33:30.306869', '2026-02-08 19:33:30.306869', '648b5c73-74e4-4ccd-9313-dce53be9d171', 'low', 'eeccb5f5-fa6f-4cf5-9d09-c56c9b21cf88') ON CONFLICT DO NOTHING;
INSERT INTO public.skills VALUES ('95ea3c23-9860-44fa-bf60-47fbd6d69bb9', 'browser-automation', 'Browser Automation', 'Playwright-based browser control for web scraping, form filling, and automated navigation. One of the most popular skills.', 'Browser Automation is a powerful OpenClaw skill that provides complete control over web browsers using Playwright. It enables automated web scraping, form submission, screenshot capture, PDF generation, and complex multi-step browser workflows. Perfect for automating repetitive web tasks, data extraction, and testing.', 'steipete', NULL, '2.3.0', 'automation', 4200, 125000, 45000, 89000, 92, 'verified', true, true, '# Browser Automation Skill
